  const min = (v) => (Number.isFinite(v) ? v : 0);
  switch (role) {
    case "Printer Operator":   return (min(calc.printMinutes)) / 60;
    case "Cutter Operator":    return (min(calc.cutMinutes)) / 60;
    case "Laminator Operator": return (min(calc.laminateMinutes)) / 60;
