      {WORKFLOW_PRESETS.map(p => {
        const active = activePresetKey === p.key;
        return (
          <Button
            key={p.key}
            size="sm"
            variant={active ? "default" : "outline"}
            onClick={() => onApply(p)}
            className={`h-7 text-[11px] ${active ? "bg-blue-600 hover:bg-blue-700 text-white" : "bg-white"}`}
            title={p.description}
          >
            {p.label}
          </Button>
        );
      })}
    </div>
  );
}

