  { id: "reflective",          label: "Reflective" },
  { id: "perforated_window",   label: "Perforated Window" },
  { id: "etched_glass",        label: "Etched / Frosted Glass" },
  { id: "fluorescent",         label: "Fluorescent" },
  { id: "metallic",            label: "Metallic" },
